import{_ as a,o as t,c as n,ag as o}from"./chunks/framework.D9ghT4bC.js";const c=JSON.parse('{"title":"Translation generation - for modders","description":"","frontmatter":{},"headers":[],"relativePath":"Translating/Translation-mods.md","filePath":"Translating/Translation-mods.md"}'),r={name:"Translating/Translation-mods.md"};function s(i,e,l,d,h,p){return t(),n("div",null,[...e[0]||(e[0]=[o(`<h1 id="translation-generation-for-modders" tabindex="-1">Translation generation - for modders <a class="header-anchor" href="#translation-generation-for-modders" aria-label="Permalink to &quot;Translation generation - for modders&quot;">​</a></h1><h2 id="generating-needs-translation-entries" tabindex="-1">Generating &quot;needs translation&quot; entries <a class="header-anchor" href="#generating-needs-translation-entries" aria-label="Permalink to &quot;Generating &quot;needs translation&quot; entries&quot;">​</a></h2><p>If you can run desktop with the mod installed, then provide at least one valid translation of something that is present in your mod or the base game in that file. The file can be empty otherwise. Do this for each language you want to support. Now run Unciv and use options-advanced-&quot;Generate translation files&quot;. Note you can and should choose your mod here to limit what the generator processes. Reload your translation file and it will have added all the necessary &quot;requires translation&quot; entries specific to your mod. (I repeat, works only if there&#39;s at least one valid entry already there). You can also override base game translations, but those won&#39;t be output by the &quot;Generate translation files&quot; tool.</p><p>Here&#39;s an example: Say you have a new nation in your mod named &quot;The Borg&quot;. You create the translations folder, create an empty file named, say, &quot;Hungarian.properties&quot;, add &quot;The Borg = The Borg&quot; to that, run Unciv and run the translation generator from options. Reload the new file, bingo all what Unciv would like to see is there.</p><p>If you&#39;re modding on Android only - don&#39;t. That said, it&#39;s not impossible, just make do without the described tool and add everything yourself, test, rinse, repeat. Be aware that the game does not read changed files from disk if it doesn&#39;t need to, so on Droid you could either edit locally and force-stop to ensure changes are read, or edit on a github repo and re-install from there, or...</p><p>Adding new languages in a mod is not supported. See <a href="./Translating.html#adding-a-new-language">Adding a new language</a> on how to do that properly.</p><p>Remember, exact case is important both in translation keys to the left of the &quot;=&quot; and file names.</p><h2 id="more-about-translating" tabindex="-1">More about translating <a class="header-anchor" href="#more-about-translating" aria-label="Permalink to &quot;More about translating&quot;">​</a></h2><p>Sometimes you&#39;ll see a <code>English.properties</code> in the translation folder. For example, if you see <code>gold = credits</code> in <code>English.properties</code>, It means the word &#39;gold&#39; will be displayed as &#39;credits&#39; in the English version. So in your translation file, though &#39;gold&#39; is already translated in vanilla unciv, you should still translate the line.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gold = credits ( &lt;- in your language)</span></span>
<span class="line"><span>NOT:gold = gold ( &lt;- in your language)</span></span></code></pre></div><p>(The example comes from the mod <a href="https://github.com/carriontrooper/Alpha-Frontier" target="_blank" rel="noreferrer">Alpha-Frontier</a>. Thanks @carriontrooper.)</p><p>Most Base Ruleset mods contain this feature, so you&#39;d better be careful translating those, or you&#39;ll make the translation work really &#39;amuzing&#39;😄</p><p>Another thing about translation is &#39;extra translating&#39;. The aim of &#39;extra translating&#39; is to make your mod translation closer to the gaming content and give the players a better gaming experience. A great example is from @SpacedOutChicken&#39;s mod Deciv. @The Bucketeer made some &#39;extra translations&#39; which are excellent.<a href="https://github.com/SpacedOutChicken/DeCiv-Redux/blob/main/jsons/translations/Traditional_Chinese.properties" target="_blank" rel="noreferrer">(link is here)</a>I&#39;ve got a few lines here so you can take it as a reference.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Your warmongering ways are unacceptable to us. = 即使在野蠻的荒土世界，窮兵黷武的行徑還是無法容忍的！</span></span>
<span class="line"><span>(English meaning: These warmongering ways are still unaccepable enen in this world of savage)</span></span></code></pre></div>`,14)])])}const g=a(r,[["render",s]]);export{c as __pageData,g as default};
